/**
 * The real templates, as the API really returns them, through this renderer.
 *
 * Every other test here feeds a fixture written to exercise one rule. This one
 * reads payloads produced by the platform's own transform from the templates
 * an author actually starts from, so it asks the question that matters: would
 * a person see this message.
 *
 * Generated by the platform repo's tests/message-pipeline-simulation.test.ts
 * with TOLINKU_SIM_DIR set. Absent those, it falls back to an inline copy so
 * it still runs anywhere, and the describe says which mode it used.
 */

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import fs from 'fs';
import path from 'path';
import { Messages } from '../src/messages.js';
import type { HttpClient } from '../src/client.js';
import type { Message, MessageAppContext } from '../src/types.js';

const SIM_FILE = process.env.TOLINKU_SIM_DIR
  ? path.join(process.env.TOLINKU_SIM_DIR, 'message-payloads.json')
  : '';

const FALLBACK_APP: MessageAppContext = {
  name: 'Example',
  icon_url: 'https://cdn.example.com/icon.png',
  ios_store_url: 'https://apps.apple.com/app/id1',
  android_store_url: 'https://play.google.com/store/apps/details?id=x',
  deep_link_url: 'https://links.example.com/install',
  ios_badge_url: 'https://links.example.com/images/defaults/badges/ios-store-badge-black.png',
  android_badge_url: 'https://links.example.com/images/defaults/badges/play-store-badge-black.png',
};

const FALLBACK_PAYLOADS = [
  {
    id: 'inline-announcement',
    app: FALLBACK_APP,
    content: {
      root: { props: { bgColor: '#ffffff', padding: 20, contentWidth: 480 } },
      content: [
        { type: 'Spacer', props: { id: 's1', height: 8 } },
        { type: 'Image', props: { id: 'i1', url: 'https://links.example.com/images/defaults/icons/bell.png', width: '44px', borderRadius: 0 } },
        { type: 'Heading', props: { id: 'h1', text: 'Something new', fontSize: 24, alignment: 'center' } },
        { type: 'TextBlock', props: { id: 't1', content: 'Read the [notes](https://example.com/notes).', alignment: 'center' } },
        { type: 'Button', props: { id: 'b1', label: 'Open', action: 'myapp://order/4821', style: 'soft', bgColor: '#1B1B1B', borderRadius: 0 } },
      ],
    },
  },
];

const payloads: any[] =
  SIM_FILE && fs.existsSync(SIM_FILE)
    ? JSON.parse(fs.readFileSync(SIM_FILE, 'utf8'))
    : FALLBACK_PAYLOADS;

const usingGenerated = !!(SIM_FILE && fs.existsSync(SIM_FILE));

function makeClient(): HttpClient {
  return {
    post: vi.fn().mockResolvedValue({}),
    get: vi.fn().mockResolvedValue({ messages: [] }),
    getPublic: vi.fn().mockResolvedValue({}),
    postPublic: vi.fn().mockResolvedValue({}),
    abort: vi.fn(),
  } as unknown as HttpClient;
}

let client: HttpClient;
let messages: Messages;

beforeEach(() => {
  document.body.innerHTML = '';
  document.head.innerHTML = '';
  client = makeClient();
  messages = new Messages(client);
});

afterEach(() => {
  document.body.innerHTML = '';
  document.head.innerHTML = '';
});

async function showPayload(payload: any): Promise<HTMLElement> {
  const message: Message = {
    id: payload.id,
    name: payload.id,
    title: 'Fallback title',
    body: 'Fallback body',
    trigger: 'manual',
    trigger_value: '',
    content: payload.content,
    background_color: '#ffffff',
    priority: 10,
    dismiss_days: null,
    max_impressions: null,
    min_interval_hours: null,
  };
  (client.get as ReturnType<typeof vi.fn>).mockResolvedValue({ messages: [message], app: payload.app });
  await messages.show({});
  const card = document.querySelector('.tolk-msg-card') as HTMLElement;
  expect(card).not.toBeNull();
  return card;
}

describe(`stock message templates on this renderer (${usingGenerated ? 'generated payloads' : 'inline fallback'})`, () => {
  it('has payloads to render', () => {
    expect(payloads.length).toBeGreaterThan(0);
  });

  for (const payload of payloads) {
    describe(payload.id, () => {
      it('draws the designed content, not the title and body fallback', async () => {
        const card = await showPayload(payload);
        // The fallback firing here would mean nothing in the content drew.
        expect(card.textContent).not.toContain('Fallback title');
        expect(card.children.length).toBeGreaterThan(1);
      });

      it('draws every image it names, with a real source', async () => {
        const card = await showPayload(payload);
        const wanted = payload.content.content.filter((c: any) => c.type === 'Image').length;
        const imgs = Array.from(card.querySelectorAll('img'));
        expect(imgs.length).toBeGreaterThanOrEqual(wanted);
        for (const img of imgs) {
          expect(img.getAttribute('src')).toMatch(/^https?:\/\//);
          expect(img.getAttribute('src')).not.toMatch(/\.svg$/i);
        }
      });

      it('draws every button with a label', async () => {
        const card = await showPayload(payload);
        const wanted = payload.content.content.filter((c: any) => c.type === 'Button' || c.type === 'DeepLinkButton').length;
        const buttons = Array.from(card.querySelectorAll('button:not(.tolk-msg-close)'));
        expect(buttons.length).toBe(wanted);
        for (const b of buttons) expect(String(b.textContent).trim().length).toBeGreaterThan(0);
      });
    });
  }
});

describe('a section, which the stock templates do not use', () => {
  it('draws its children instead of an empty box', async () => {
    const card = await showPayload({
      id: 'synthetic-section',
      app: payloads[0]?.app || FALLBACK_APP,
      content: {
        root: { props: {} },
        content: [{ type: 'Section', props: { id: 'sec1', bgColor: '#f5f5f5', padding: 0 } }],
        zones: {
          'sec1:content': [
            { type: 'Heading', props: { id: 'h', text: 'Inside the section' } },
            { type: 'Button', props: { id: 'b', label: 'Go', action: 'myapp://inside' } },
          ],
        },
      },
    });

    expect(card.textContent).toContain('Inside the section');
    expect(card.querySelectorAll('button:not(.tolk-msg-close)')).toHaveLength(1);
    expect(card.textContent).not.toContain('Fallback title');
  });
});
